"""Make `nbp` (src/) importable and skip tests that need the fetched SMLP4Rec class if absent."""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "src"
if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))

# src/nbp/models/smlprec.py is generated by scripts/fetch_smlp4rec.py (upstream has no license)
if not (SRC / "nbp" / "models" / "smlprec.py").exists():
    collect_ignore = ["test_scorers.py", "test_smlprec_query.py", "test_train.py"]
